"""
Structural Verilog writer and self-checking testbench generator.

The module only instantiates Verilog gate primitives (not / and / or / buf),
one instance per netlist gate, so it is purely structural.
"""

from datetime import datetime


def emit_module(nl, source=""):
    st = nl.stats()
    by_type = ", ".join(f"{v} {k}" for k, v in sorted(st["by_type"].items()))
    lines = [
        "// " + "-" * 70,
        "// Structural Verilog generated by logicsynth (EC551 Logic Synthesis Engine)",
        f"// Source    : {source}",
        f"// Generated : {datetime.now():%Y-%m-%d %H:%M}",
        f"// Gates     : {st['gates']} logic gates ({by_type}), "
        f"{st['gate_inputs']} gate inputs, depth {st['depth']}",
    ]
    for o in nl.outputs:
        lines.append(f"// {o} [{nl.forms[o]}] = {nl.expressions[o]}")
    lines.append("// " + "-" * 70)
    ports = [f"    input  wire {i}" for i in nl.inputs] + [f"    output wire {o}" for o in nl.outputs]
    lines.append(f"module {nl.module} (")
    lines.append(",\n".join(ports))
    lines.append(");")
    if nl.wires:
        lines.append("")
        for k in range(0, len(nl.wires), 8):
            lines.append("    wire " + ", ".join(nl.wires[k:k + 8]) + ";")
    lines.append("")
    width = max((len(g.kind) for g in nl.gates), default=3)
    for idx, g in enumerate(nl.gates):
        lines.append(f"    {g.kind.ljust(width)} g{idx} ({g.output}, {', '.join(g.inputs)});")
    lines.append("")
    lines.append("endmodule")
    return "\n".join(lines) + "\n"


def emit_testbench(nl, design, max_inputs=16):
    """Exhaustive testbench comparing the module against the engine's truth table.

    Expected ON-set / don't-care set of each output are embedded as 2**n-bit
    constants; don't-care points are skipped.
    """
    n = len(nl.inputs)
    if n > max_inputs:
        return None
    size = 1 << n
    # Testbench-internal names use a "tb__" prefix so they cannot clash with ports.
    lines = [
        "// Self-checking exhaustive testbench generated by logicsynth",
        "`timescale 1ns / 1ps",
        f"module tb_{nl.module};",
        f"    reg  [{n - 1}:0] tb__x;",
    ]
    for o in nl.outputs:
        lines.append(f"    wire {o};")
    for o, fn in zip(nl.outputs, design.outputs.values()):
        lines.append(f"    localparam [{size - 1}:0] {o}_ON = {size}'h{fn.on_vec:x};")
        lines.append(f"    localparam [{size - 1}:0] {o}_DC = {size}'h{fn.dc_vec:x};")
    conns = [f".{name}(tb__x[{n - 1 - i}])" for i, name in enumerate(nl.inputs)]
    conns += [f".{o}({o})" for o in nl.outputs]
    lines.append(f"    {nl.module} dut ({', '.join(conns)});")
    lines += [
        "    integer tb__i, tb__errors;",
        "    initial begin",
        "        tb__errors = 0;",
        f"        for (tb__i = 0; tb__i < {size}; tb__i = tb__i + 1) begin",
        "            tb__x = tb__i;",
        "            #1;",
    ]
    for o in nl.outputs:
        lines += [
            f"            if (!{o}_DC[tb__i] && {o} !== {o}_ON[tb__i]) begin",
            f"                tb__errors = tb__errors + 1;",
            f"                $display(\"MISMATCH m%0d: {o}=%b expected %b\", tb__i, {o}, {o}_ON[tb__i]);",
            "            end",
        ]
    lines += [
        "        end",
        f"        if (tb__errors == 0) $display(\"PASS: {nl.module} matches the specification on all {size} input combinations\");",
        "        else $display(\"FAIL: %0d mismatches\", tb__errors);",
        "        $finish;",
        "    end",
        "endmodule",
    ]
    return "\n".join(lines) + "\n"
